create or replace function public.activate_seller_pilot(p_user_id uuid,p_admin_id uuid,p_daily_limit integer default 10,p_label text default null) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_total integer; v_row public.seller_pilot_access%rowtype; v_started timestamptz; v_ends timestamptz; begin perform pg_advisory_xact_lock(hashtext('seller-pilot-capacity')); if p_daily_limit <> 10 then return jsonb_build_object('ok',false,'reason','INVALID_DAILY_LIMIT','required',10); end if; if not exists(select 1 from auth.users where id=p_user_id) then return jsonb_build_object('ok',false,'reason','USER_NOT_FOUND'); end if; select * into v_row from public.seller_pilot_access where user_id=p_user_id; if found and v_row.status='active' and v_row.ends_at>now() then return jsonb_build_object('ok',true,'already_active',true,'started_at',v_row.started_at,'ends_at',v_row.ends_at,'daily_limit',v_row.daily_limit,'total_limit',v_row.total_limit,'pilot_label',v_row.pilot_label); end if; select count(*) into v_total from public.seller_pilot_access where status='active' and ends_at>now() and user_id<>p_user_id; if v_total>=6 then return jsonb_build_object('ok',false,'reason','PILOT_CAPACITY_REACHED','limit',6); end if; v_started:=now(); v_ends:=v_started+interval '5 days'; delete from public.seller_pilot_daily_usage where user_id=p_user_id; insert into public.seller_pilot_access(user_id,started_at,ends_at,status,created_by,daily_limit,total_limit,pilot_label) values(p_user_id,v_started,v_ends,'active',p_admin_id,10,50,nullif(trim(p_label),'')) on conflict(user_id) do update set started_at=excluded.started_at,ends_at=excluded.ends_at,status='active',created_by=excluded.created_by,created_at=now(),daily_limit=10,total_limit=50,pilot_label=excluded.pilot_label; update public.profiles set marketplace_access=array['takealot']::text[],updated_at=now() where id=p_user_id; return jsonb_build_object('ok',true,'already_active',false,'started_at',v_started,'ends_at',v_ends,'daily_limit',10,'total_limit',50,'marketplace_access',jsonb_build_array('takealot'),'pilot_label',nullif(trim(p_label),'')); end; $$; revoke all on function public.activate_seller_pilot(uuid,uuid,integer,text) from public,anon,authenticated; grant execute on function public.activate_seller_pilot(uuid,uuid,integer,text) to service_role;